def fingerprint(raw):
    return hashlib.md5(raw.replace(b"\r\n", b"\n")).hexdigest()


def main():
    if os.path.basename(os.getcwd()) == "documentation":
        raise SystemExit("ERROR: run this from the GALLERY repo ROOT, next to "
                         "interactive.html -- not from documentation/. "
                         "NOTHING was written.")
    if not os.path.isfile("interactive.html"):
        raise SystemExit("ERROR: interactive.html is not here, so this is "
                         "not the gallery root. NOTHING was written.")
    for path in SPEC['NEW']:
        if os.path.exists(path):
            raise SystemExit("ERROR: %s already exists. If you already ran "
                             "this patch, it has nothing left to do. NOTHING "
                             "was written." % path)
    results = []
    for path, edits in sorted(SPEC['PLAN'].items()):
        with open(path, "rb") as handle:
            raw = handle.read()
        got = fingerprint(raw)
        if got != SPEC['BASE'][path]:
            raise SystemExit(
                "ERROR: %s is not the file this patch was built against.\n"
                "       expected %s, found %s.\n"
                "       (Line endings are excluded, so they are not the cause.)\n"
                "       NOTHING was written. Undo is Discard Changes in\n"
                "       GitHub Desktop." % (path, SPEC['BASE'][path], got))
        nl = "\r\n" if raw.count(b"\r\n") > 0 else "\n"
        text = raw.decode("utf-8")
        before = sum(1 for ch in text if ord(ch) > 127)
        done = []
        for old, new, label in edits:
            o = old.replace("\n", nl)
            n = new.replace("\n", nl)
            count = text.count(o)
            if count != 1:
                raise SystemExit("ANCHOR FAIL (%s): expected 1 match in %s, "
                                 "found %d. NOTHING was written."
                                 % (label, path, count))
            text = text.replace(o, n)
            done.append(label)
        if sum(1 for ch in text if ord(ch) > 127) > before:
            raise SystemExit("ERROR: %s would hold new non-ASCII text. "
                             "NOTHING was written." % path)
        results.append((path, text, done))

    for path, text, done in results:
        with open(path, "wb") as handle:
            handle.write(text.encode("utf-8"))
        for label in done:
            print("ok  %-28s %s" % (path, label))
    for path, content in sorted(SPEC['NEW'].items()):
        with open(path, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(content)
        print("ok  %-28s created" % path)

    print("")
    print("patch applied")
    print("")
    print("NEXT:")
    print("  1. python gallery_maintenance_run.py. Its Objects mirror writes")
    print("     the eleven bodies' words and links into the config and")
    print("     prints every field it moved; Apophis's Horizons id becomes")
    print("     2004 MN4.")
    print("  2. Cache in step will FAIL on that run, naming Apophis's")
    print("     horizons_id. That is expected: run daily_run.py to rebuild")
    print("     the cache, then run the maintenance run again.")
    print("  3. Move this script into documentation/; commit and push.")


if __name__ == "__main__":
    main()
